// A grow buffer (64 bytes allocated) with 5 bytes written: only the 5 bytes should reach Steam Cloud
var b = buffer_create(64, buffer_grow, 1);
repeat (5) buffer_write(b, buffer_u8, 7);
var ok = steam_remote_storage_file_write("gametest_cw_sync.bin", b);
buffer_delete(b);
return ok ? 1 : 0;

var b = buffer_create(64, buffer_grow, 1);
repeat (5) buffer_write(b, buffer_u8, 7);
var ok = steam_remote_storage_file_write("gametest_cw_offset.bin", b, 2);
buffer_delete(b);
return ok ? 1 : 0;

// Position not past the offset (as after buffer_load): falls back to the buffer size minus the offset
var b = buffer_create(64, buffer_grow, 1);
repeat (5) buffer_write(b, buffer_u8, 7);
buffer_seek(b, buffer_seek_start, 0);
var ok = steam_remote_storage_file_write("gametest_cw_pos0.bin", b);
buffer_delete(b);
return ok ? 1 : 0;

var b = buffer_create(64, buffer_grow, 1);
repeat (5) buffer_write(b, buffer_u8, 7);
steam_remote_storage_file_write_async("gametest_cw_async.bin", b, gametest_async_recorder("cw_async"));
buffer_delete(b);
return 1;

// An explicit count of 0 now calls back with Fail instead of never calling back
var b = buffer_create(64, buffer_grow, 1);
repeat (5) buffer_write(b, buffer_u8, 7);
steam_remote_storage_file_write_async("gametest_cw_zero.bin", b, gametest_async_recorder("cw_zero"), 0, 0);
buffer_delete(b);
return 1;

var s = steam_remote_storage_file_write_stream_open("gametest_cw_stream.bin");
var b = buffer_create(64, buffer_grow, 1);
repeat (5) buffer_write(b, buffer_u8, 7);
var ok = steam_remote_storage_file_write_stream_write_chunk(s, b);
buffer_delete(b);
return (ok && steam_remote_storage_file_write_stream_close(s)) ? 1 : 0;

var n = steam_remote_storage_get_file_size("gametest_cw_sync.bin");
show_debug_message("gametest: sync file size " + string(n));
return n;

var n = steam_remote_storage_get_file_size("gametest_cw_offset.bin");
show_debug_message("gametest: offset file size " + string(n));
return n;

var n = steam_remote_storage_get_file_size("gametest_cw_pos0.bin");
show_debug_message("gametest: pos0 file size " + string(n));
return n;

var n = steam_remote_storage_get_file_size("gametest_cw_async.bin");
show_debug_message("gametest: async file size " + string(n));
return n;

var n = steam_remote_storage_get_file_size("gametest_cw_stream.bin");
show_debug_message("gametest: stream file size " + string(n));
return n;

var ok = true;
var names = ["gametest_cw_sync.bin", "gametest_cw_offset.bin", "gametest_cw_pos0.bin", "gametest_cw_async.bin", "gametest_cw_stream.bin"];
for (var i = 0; i < array_length(names); i++) ok = steam_remote_storage_file_delete(names[i]) && ok;
return ok ? 1 : 0;
